compile.workshop:
variables {
    global:
        0: g
        1: h
    player:
        0: p
}

//Strict optimizations enabled
rule ("operators") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is Dummy Bot(Event Player) == True;
        Is Alive(Event Player) == True;
        (Event Player).p == False;
        (Event Player).p != True;
        (Event Player).p != False;
        Global.h > 0;
    }
    actions {
        Set Global Variable(g, -5);
        Set Global Variable(g, Multiply(1, Global.h));
        Set Global Variable(g, 5);
        Set Global Variable(g, Add(-5, Global.h));
        Set Global Variable(g, True);
        Set Global Variable(g, False);
        Set Global Variable(g, False);
        Set Global Variable(g, And(Compare(Global.h, >, 1), True));
        Set Global Variable(g, 1);
        Set Global Variable(g, Multiply(Global.h, 0));
        Set Global Variable(g, Add(Global.h, 0));
        Set Global Variable(g, Multiply(-1, Global.h));
        Set Global Variable(g, Compare(Global.h, !=, 1));
        Set Global Variable(g, Is Alive(Event Player));
        Set Global Variable(g, Compare(Custom String("am"), ==, Custom String("**")));
    }
}

